import { afterEach, describe, expect, it, vi } from "vitest";
import {
  audioPacket,
  flacTrack,
  makePipelinePlayer,
  packetRun,
  videoPacket,
  type DecoderShape,
} from "../helpers/pipeline-player";

// dist/wasm/movi.js is generated by build:wasm and absent in the unit-test
// job; MoviPlayer's module graph imports it eagerly, so stub the module the
// same way the other MoviPlayer-importing suites already do.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));
vi.mock("dashjs", () => ({ MediaPlayer: vi.fn() }));
vi.mock("shaka-player/dist/shaka-player.compiled", () => ({
  default: {
    Player: { isBrowserSupported: vi.fn(() => false) },
    polyfill: { installAll: vi.fn() },
    net: { NetworkingEngine: { RequestType: { LICENSE: 1 } } },
  },
}));

afterEach(() => {
  vi.unstubAllGlobals();
});

const hwVideo = (queueSize: number): DecoderShape => ({ isSoftware: false, worker: false, queueSize });
const hwAudio = (queueSize: number): DecoderShape => ({ isSoftware: false, worker: false, queueSize });
const idleAudio = hwAudio(0);
const idleVideo = hwVideo(0);

/** Whether one queued video packet is handed to a decoder holding `video.queueSize`. */
async function feedsVideoAt(video: DecoderShape, opts: { waitingForVideoSync?: boolean } = {}) {
  const f = await makePipelinePlayer({
    video,
    audio: idleAudio,
    waitingForVideoSync: opts.waitingForVideoSync,
    // The renderer is far under any maxVideoBuffered floor, so only the
    // decoder-queue cap under test can hold the packet back.
    rendererQueue: 5,
    queuedVideo: [videoPacket(10, true)],
  });
  await f.tick();
  return f.videoDecode.mock.calls.length > 0;
}

async function feedsAudioAt(audio: DecoderShape, opts: { waitingForVideoSync?: boolean } = {}) {
  const f = await makePipelinePlayer({
    video: idleVideo,
    audio,
    // Under every maxAudioBuffered branch, so only the decoder-queue cap
    // under test can hold the packet back.
    audioBuffered: 0.5,
    // A seek waiting for its first VIDEO frame holds audio back whatever the
    // cap; the relaxed seek cap is what an audio-only seek is fed against.
    tracks: opts.waitingForVideoSync ? [flacTrack] : undefined,
    waitingForVideoSync: opts.waitingForVideoSync,
    queuedAudio: [audioPacket(10)],
  });
  await f.tick();
  return f.audioDecode.mock.calls.length > 0;
}

/**
 * P2 — `maxVideoQueue`/`maxAudioQueue` pick a decoder-queue ceiling based on
 * whether the software decode is running in a worker (offloaded, deep queue
 * tolerated), main-thread software (shallow main-thread budget), or hardware
 * (WebCodecs baseline, relaxed while a seek waits for its first frame).
 *
 * These used to gate `demuxer.readPacket()` itself. Since the pull pipeline
 * (docs/PLAN_MOVI_PIPELINE.md P1) they gate only what is FED to that decoder:
 * a packet stays in its stream's queue until the decoder is back under its
 * cap, and the other stream keeps reading and decoding meanwhile.
 */
describe("MoviPlayer P2: decodeMode-driven video decoder queue cap", () => {
  it("worker-offloaded software video: feeds at 47, holds at 49 (cap 48)", async () => {
    expect(await feedsVideoAt({ isSoftware: true, worker: true, queueSize: 47 })).toBe(true);
    expect(await feedsVideoAt({ isSoftware: true, worker: true, queueSize: 49 })).toBe(false);
  }, 20_000);

  it("main-thread software video: feeds at 999, holds at 1001 (cap 1000)", async () => {
    expect(await feedsVideoAt({ isSoftware: true, worker: false, queueSize: 999 })).toBe(true);
    expect(await feedsVideoAt({ isSoftware: true, worker: false, queueSize: 1001 })).toBe(false);
  }, 20_000);

  it("hardware video, steady state: feeds at 29, holds at 31 (cap 30)", async () => {
    expect(await feedsVideoAt(hwVideo(29))).toBe(true);
    expect(await feedsVideoAt(hwVideo(31))).toBe(false);
  }, 20_000);

  it("hardware video, waitingForVideoSync: cap relaxes to 60 (feeds at 59, holds at 61)", async () => {
    expect(await feedsVideoAt(hwVideo(59), { waitingForVideoSync: true })).toBe(true);
    expect(await feedsVideoAt(hwVideo(61), { waitingForVideoSync: true })).toBe(false);
  }, 20_000);
});

/**
 * A full video decoder right after a seek must cost nothing but video's own
 * progress — no dropped deltas, no stopped audio.
 *
 * Under the old push loop, "audio under 0.1s with the video decoder full"
 * dropped the next delta and latched `videoChainBrokenUntilKeyframe`, so every
 * delta up to the NEXT keyframe was thrown away. Right after a seek the audio
 * buffer reads 0 without starving — held while the seek waits for its first
 * frame, then sitting in the audio decoder for a few hundred ms — and both
 * moments coincide with the burst after the target keyframe filling the video
 * decoder. On a 10s-GOP x264 file (the 萤火虫之墓 shape, local loopback
 * 2026-10-05) the picture sat on the seek frame for ~3s of running clock and
 * then jumped to the next keyframe. The same latch fired at an audio track
 * switch, which empties the audio side on purpose.
 *
 * With per-stream queues the delta read past a full decoder waits in the
 * video queue, and audio is read and fed on its own account.
 */
describe("MoviPlayer: a full video decoder around a seek", () => {
  it("keeps the delta queued, in order, while the seek holds audio back", async () => {
    const f = await makePipelinePlayer({
      video: hwVideo(61),
      audio: idleAudio,
      audioBuffered: 0,
      waitingForVideoSync: true,
      rendererQueue: 0,
      reads: [deltaVideoPacket()],
    });
    await f.tick();
    expect(f.videoDecode).not.toHaveBeenCalled();
    expect(f.player.videoQueue.length).toBe(1);
    expect(f.player.videoQueue.peek().timestamp).toBe(30.07);
  }, 20_000);

  it("keeps the delta queued while audio packets are still in their decoder", async () => {
    const f = await makePipelinePlayer({
      video: hwVideo(54),
      audio: { isSoftware: true, worker: true, queueSize: 29 },
      audioBuffered: 0,
      reads: [deltaVideoPacket()],
    });
    await f.tick();
    expect(f.videoDecode).not.toHaveBeenCalled();
    expect(f.player.videoQueue.length).toBe(1);
  }, 20_000);

  it("keeps the delta queued while audio is being rebuilt for a track switch", async () => {
    const f = await makePipelinePlayer({
      video: hwVideo(54),
      audioBuffered: 0,
      reads: [deltaVideoPacket()],
    });
    f.player._audioSwitching = true;
    f.player._audioDecoderConfiguring = true;
    await f.tick();
    expect(f.videoDecode).not.toHaveBeenCalled();
    expect(f.player.videoQueue.length).toBe(1);
  }, 20_000);

  // The case the old delta-drop existed for: audio dry with nothing left to
  // decode while the video decoder is full. The cure is reading the audio,
  // which is now always allowed; the video chain is left intact.
  it("reads and feeds audio when it is dry, instead of dropping video", async () => {
    const f = await makePipelinePlayer({
      video: hwVideo(54),
      audio: { isSoftware: true, worker: true, queueSize: 0 },
      audioBuffered: 0,
      reads: [deltaVideoPacket(), audioPacket(30.05)],
    });
    await f.tick();
    expect(f.videoDecode).not.toHaveBeenCalled();
    expect(f.player.videoQueue.length).toBe(1);
    expect(f.audioDecode).toHaveBeenCalledTimes(1);
  }, 20_000);
});

function deltaVideoPacket() {
  return videoPacket(30.07, false, 16);
}

/**
 * A rebuffer that is waiting for an AUDIO cushion must be able to read it.
 *
 * The resume gate asks software / cold-primed audio for a 2s cushion. A
 * hardware video decoder only emits into free output surfaces, and with the
 * presentation loop stopped for buffering the renderer frees none — so once
 * the renderer holds its handful of frames the decoder's queue sits at its
 * cap. When that cap gated every read, the audio cushion could never grow: no
 * reads, no cushion; no cushion, no resume; no resume, no drain. Loopback
 * 1080p x264 + software AAC, 2026-10-05: stuck at 1.837s against the 2.0s
 * target, decoder queue 31 against a cap of 30, renderer holding 8 frames at
 * the playhead, until the element's stuck-watchdog fired a full seek.
 */
describe("MoviPlayer: rebuffer waiting for an audio cushion", () => {
  async function stuckRebuffer(audioBuffered: number, extra: Record<string, unknown> = {}, opts: Parameters<typeof makePipelinePlayer>[0] = {}) {
    const f = await makePipelinePlayer({
      state: "buffering",
      video: hwVideo(31),
      audio: { isSoftware: true, worker: true, queueSize: 0 },
      audioBuffered,
      rendererQueue: 8,
      ...opts,
    });
    Object.assign(f.player, { _primingAudio: true, ...extra });
    await f.tick();
    return f;
  }

  it("reads and feeds audio past a full video decoder while audio is short of its target", async () => {
    const f = await stuckRebuffer(1.837, {}, {
      queuedVideo: packetRun((t) => videoPacket(t), 37, 43, 1 / 24),
      reads: [audioPacket(39.5), audioPacket(39.52)],
    });
    expect(f.readPacket).toHaveBeenCalled();
    expect(f.audioDecode).toHaveBeenCalledTimes(2);
  }, 20_000);

  it("never feeds the video decoder past its cap to do so", async () => {
    const f = await stuckRebuffer(1.837, {}, {
      queuedVideo: packetRun((t) => videoPacket(t), 37, 43, 1 / 24),
      reads: [audioPacket(39.5)],
    });
    expect(f.videoDecode).not.toHaveBeenCalled();
  }, 20_000);

  // The switch's refresh seek is issued with the discard flip, so the new
  // track has packets to give from the first read — nothing waits for a
  // reposition to land (that wait is what let the loop pour the rest of the
  // file into the video side: 1953 queued chunks on the loopback run, the
  // forward scan to EOF that costs 9-21 MB over a real link). Its packets are
  // read at once and wait in the queue until the new decoder is configured.
  it("reads for the new audio right after a track switch and holds it until the new decoder is ready", async () => {
    const f = await stuckRebuffer(0, { _audioDecoderConfiguring: true }, {
      queuedVideo: packetRun((t) => videoPacket(t), 37, 43, 1 / 24),
      reads: [audioPacket(37.9)],
    });
    expect(f.readPacket).toHaveBeenCalled();
    expect(f.player.audioQueue.length).toBe(1);
    expect(f.audioDecode).not.toHaveBeenCalled();
  }, 20_000);

  // And never without bound: the queues together stop at their byte ceiling.
  it("stops at the byte ceiling even while the cushion is still short", async () => {
    const f = await stuckRebuffer(1.837, {}, {
      queuedVideo: packetRun((t) => videoPacket(t, false, 1024 * 1024), 37, 37 + 70 / 24, 1 / 24),
    });
    expect(f.readPacket).not.toHaveBeenCalled();
  }, 20_000);
});

describe("MoviPlayer P2: decodeMode-driven audio decoder queue cap", () => {
  it("worker-offloaded software audio: feeds at 95, holds at 97 (cap 96)", async () => {
    expect(await feedsAudioAt({ isSoftware: true, worker: true, queueSize: 95 })).toBe(true);
    expect(await feedsAudioAt({ isSoftware: true, worker: true, queueSize: 97 })).toBe(false);
  }, 20_000);

  it("main-thread software audio: feeds at 39, holds at 41 (cap 40)", async () => {
    expect(await feedsAudioAt({ isSoftware: true, worker: false, queueSize: 39 })).toBe(true);
    expect(await feedsAudioAt({ isSoftware: true, worker: false, queueSize: 41 })).toBe(false);
  }, 20_000);

  it("hardware audio, steady state: feeds at 19, holds at 21 (cap 20)", async () => {
    expect(await feedsAudioAt(hwAudio(19))).toBe(true);
    expect(await feedsAudioAt(hwAudio(21))).toBe(false);
  }, 20_000);

  it("hardware audio, waitingForVideoSync: cap relaxes to 40 (feeds at 39, holds at 41)", async () => {
    expect(await feedsAudioAt(hwAudio(39), { waitingForVideoSync: true })).toBe(true);
    expect(await feedsAudioAt(hwAudio(41), { waitingForVideoSync: true })).toBe(false);
  }, 20_000);
});
